/**
 * The licence notices the app is obliged to show.
 *
 * Apache-2.0 — which @tetherto/wdk and 181 other production dependencies use — requires that
 * a distributed work carry the licence and any notices. Shipping without them is a compliance
 * problem on the day the app is distributed.
 *
 * The data is generated by `npm run notices`, never edited by hand, and the texts are
 * deduplicated: 742 packages share 256 distinct licence files, so storing one copy each took
 * the payload from 2.7MB to 549KB. That matters for users on metered data.
 */
import data from '../generated/notices.ts';

export type Notice = {
  name: string;
  version: string;
  /** SPDX identifier, or 'UNKNOWN' where a package declares none. */
  license: string;
  homepage: string;
  /** Index into the shared texts, or -1 when the package ships no licence file. */
  textRef: number;
};

/**
 * Sorted once, not per call.
 *
 * The screen filters this on every keystroke, and re-sorting 742 entries each time is work
 * nobody asked for on a phone. The array is treated as read-only by every caller.
 */
let sorted: Notice[] | null = null;

export function allNotices(): Notice[] {
  sorted ??= (data.packages as Notice[]).slice().sort((a, b) => a.name.localeCompare(b.name));
  return sorted;
}

/**
 * Name or licence, case-insensitive.
 *
 * Searching matters more here than it looks: 742 rows is not a list anyone scrolls. The two
 * things a person actually arrives wanting are "is <package> in here" and "show me everything
 * under <licence>", so both are one query rather than two features.
 */
export function searchNotices(query: string): Notice[] {
  const needle = query.trim().toLowerCase();
  if (!needle) return allNotices();
  return allNotices().filter(n => n.name.toLowerCase().includes(needle) || n.license.toLowerCase().includes(needle));
}

/** The full licence text for a package, or null where it shipped none. */
export function noticeText(notice: Notice): string | null {
  if (notice.textRef < 0) return null;
  return (data.texts as string[])[notice.textRef] ?? null;
}

/** For the summary line on the screen: how many packages under each licence. */
export function licenceSummary(): { license: string; count: number }[] {
  const counts = new Map<string, number>();
  for (const n of data.packages as Notice[]) counts.set(n.license, (counts.get(n.license) ?? 0) + 1);
  return [...counts].map(([license, count]) => ({ license, count })).sort((a, b) => b.count - a.count || a.license.localeCompare(b.license));
}
